import { Controller, Get, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 교육대상자 판단은 현재 사용자 ID가 edu_attendee.employee_id와 같은 것으로 본다.
// 가정: 점수 범위는 미정이라 0 이상 정수만 허용한다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isInt(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v);
  }
  return typeof v === 'string' && /^\d+$/.test(v);
}

function isEmpty(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

@Controller('api/v1')
export class FnSfr01504Controller {
  @Post('/edu-evaluations')
  @HttpCode(200)
  async createEduEvaluation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    if (!isInt(data.eduAttendeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '교육대상자를 선택해 주세요.');
    }
    if (!isInt(data.evalItemId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '평가항목을 선택해 주세요.');
    }
    if (!isEmpty(data.score) && !isInt(data.score)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '평가 점수는 0 이상의 정수여야 합니다.');
    }
    return transaction(async (db) => {
      const attendees = await db.query(
        'SELECT employee_id AS "employeeId" FROM edu_attendee WHERE edu_attendee_id = CAST(:attendeeId AS bigint)',
        { attendeeId: data.eduAttendeeId },
      );
      if (attendees.length === 0) {
        throw new ApiError(404, 'EDU_ATTENDEE_NOT_FOUND', '교육대상자를 찾을 수 없습니다.');
      }
      const mine = await db.query(
        'SELECT 1 AS ok FROM edu_attendee WHERE edu_attendee_id = CAST(:attendeeId AS bigint) AND employee_id = CAST(:userId AS bigint)',
        { attendeeId: data.eduAttendeeId, userId: user.id },
      );
      if (mine.length === 0) {
        throw new ApiError(422, 'NOT_EDU_ATTENDEE', '교육대상자만 평가를 등록할 수 있습니다.');
      }
      const items = await db.query(
        "SELECT 1 AS ok FROM edu_code WHERE edu_code_id = CAST(:itemId AS bigint) AND code_group = 'EVAL_ITEM'",
        { itemId: data.evalItemId },
      );
      if (items.length === 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '평가항목이 올바르지 않습니다.');
      }
      const dup = await db.query(
        'SELECT 1 AS ok FROM edu_evaluation WHERE edu_attendee_id = CAST(:attendeeId AS bigint) AND eval_item_id = CAST(:itemId AS bigint)',
        { attendeeId: data.eduAttendeeId, itemId: data.evalItemId },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '이미 등록된 평가항목입니다.');
      }
      const rows = await db.query(
        'INSERT INTO edu_evaluation (edu_attendee_id, eval_item_id, score, opinion, created_at, updated_at) ' +
          'VALUES (CAST(:attendeeId AS bigint), CAST(:itemId AS bigint), CAST(:score AS integer), CAST(:opinion AS text), now(), now()) ' +
          'RETURNING edu_evaluation_id AS "eduEvaluationId"',
        {
          attendeeId: data.eduAttendeeId,
          itemId: data.evalItemId,
          score: isEmpty(data.score) ? null : data.score,
          opinion: isEmpty(data.opinion) ? null : String(data.opinion),
        },
      );
      return rows[0];
    });
  }

  @Patch('/edu-evaluations/:eduEvaluationId')
  async updateEduEvaluation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const id = req.params['eduEvaluationId'];
    if (!isInt(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '교육평가 ID가 올바르지 않습니다.');
    }
    if (!isEmpty(data.score) && !isInt(data.score)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '평가 점수는 0 이상의 정수여야 합니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'UPDATE edu_evaluation SET score = COALESCE(CAST(:score AS integer), score), ' +
          'opinion = COALESCE(CAST(:opinion AS text), opinion), updated_at = now() ' +
          'WHERE edu_evaluation_id = CAST(:id AS bigint) ' +
          'RETURNING edu_evaluation_id AS "eduEvaluationId"',
        {
          id,
          score: isEmpty(data.score) ? null : data.score,
          opinion: isEmpty(data.opinion) ? null : String(data.opinion),
        },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EDU_EVALUATION_NOT_FOUND', '교육평가를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Get('/edu-evaluations')
  async listEduEvaluations(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const pageRaw = isEmpty(query['page']) ? 0 : query['page'];
    const sizeRaw = isEmpty(query['size']) ? DEFAULT_SIZE : query['size'];
    if (!isInt(pageRaw) || !isInt(sizeRaw) || Number(sizeRaw) < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    if (!isEmpty(query['eduSessionId']) && !isInt(query['eduSessionId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '교육 차수가 올바르지 않습니다.');
    }
    const page = Number(pageRaw);
    const size = Math.min(Number(sizeRaw), MAX_SIZE);
    const sessionId = isEmpty(query['eduSessionId']) ? null : query['eduSessionId'];
    return transaction(async (db) => {
      const params = { sessionId, limit: size, offset: page * size };
      const where = 'WHERE (CAST(:sessionId AS bigint) IS NULL OR a.edu_session_id = CAST(:sessionId AS bigint))';
      const items = await db.query(
        'SELECT e.edu_evaluation_id AS "eduEvaluationId", e.edu_attendee_id AS "eduAttendeeId", ' +
          'e.eval_item_id AS "evalItemId", e.score AS "score", e.opinion AS "opinion" ' +
          'FROM edu_evaluation e JOIN edu_attendee a ON a.edu_attendee_id = e.edu_attendee_id ' +
          where +
          ' ORDER BY e.edu_evaluation_id DESC LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        params,
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM edu_evaluation e JOIN edu_attendee a ON a.edu_attendee_id = e.edu_attendee_id ' + where,
        { sessionId },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }
}

