import { useState } from 'react';
import {
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  NumberInput,
  PageProps,
  Pager,
  RefName,
  Row,
  Page,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';

export default function FnSfr01504Page({ role, notify }: PageProps) {
  const [sessionInput, setSessionInput] = useState<number | string>('');
  const [sessionId, setSessionId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [attendeeId, setAttendeeId] = useState<number | string>('');
  const [itemId, setItemId] = useState<number | string>('');
  const [score, setScore] = useState<number | string>('');
  const [opinion, setOpinion] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/edu-evaluations', role, undefined, { eduSessionId: sessionId, page, size: 20 }),
    [sessionId, page, role],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const canCreate = role === '임직원';
  const canEdit = role === '인사 담당자';

  function openCreate() {
    setAttendeeId('');
    setItemId('');
    setScore('');
    setOpinion('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setScore(row.score === null || row.score === undefined ? '' : (row.score as number));
    setOpinion(row.opinion ? String(row.opinion) : '');
    setEditing(row);
  }

  async function submitCreate() {
    if (attendeeId === '') {
      throw new Error('교육대상자를 선택해 주세요.');
    }
    if (itemId === '') {
      throw new Error('평가항목을 선택해 주세요.');
    }
    await call('POST', '/edu-evaluations', role, {
      eduAttendeeId: attendeeId,
      evalItemId: itemId,
      score: score,
      opinion: opinion,
    });
    notify('교육평가를 등록했습니다.');
    setCreating(false);
    list.reload();
  }

  async function submitEdit() {
    if (!editing) {
      return;
    }
    await call('PATCH', '/edu-evaluations/' + String(editing.eduEvaluationId), role, {
      score: score,
      opinion: opinion,
    });
    notify('교육평가를 수정했습니다.');
    setEditing(null);
    list.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>평가 현황</h2>
        <Tiles items={[['조회된 평가', total]]} />
      </section>
      <section className="box span-12">
        <h2>교육평가 결과</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setSessionId(sessionInput);
          }}
          onReset={() => {
            setSessionInput('');
            setSessionId('');
            setPage(0);
          }}
        >
          <Field label="조회할 교육 차수">
            <NumberInput value={sessionInput} onChange={setSessionInput} />
          </Field>
        </Filters>
        <Band total={total}>
          {canCreate && <button onClick={openCreate}>평가 등록</button>}
        </Band>
        <DataTable
          rows={rows}
          empty="등록된 교육평가가 없습니다."
          columns={[
            { key: 'eduEvaluationId', label: '교육평가 ID' },
            {
              key: 'eduAttendeeId',
              label: '교육대상자',
              render: (r: Row) => <RefName table="edu_attendee" role={role} value={r.eduAttendeeId} />,
            },
            {
              key: 'evalItemId',
              label: '평가항목',
              render: (r: Row) => <RefName table="edu_code" role={role} value={r.evalItemId} />,
            },
            { key: 'score', label: '평가 점수' },
            { key: 'opinion', label: '평가 의견' },
            {
              key: 'actions',
              label: '처리',
              render: (r: Row) =>
                canEdit ? <button onClick={() => openEdit(r)}>수정</button> : null,
            },
          ]}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>
      {creating && (
        <Drawer title="교육평가 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="교육대상자" required>
              <LookupSelect table="edu_attendee" role={role} value={attendeeId} onChange={setAttendeeId} />
            </Field>
            <Field label="평가항목" required>
              <LookupSelect table="edu_code" role={role} value={itemId} onChange={setItemId} />
            </Field>
            <Field label="평가 점수">
              <NumberInput value={score} onChange={setScore} />
            </Field>
            <Field label="평가 의견" wide>
              <TextInput value={opinion} onChange={setOpinion} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {editing && (
        <Drawer title="교육평가 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="평가 점수">
              <NumberInput value={score} onChange={setScore} />
            </Field>
            <Field label="평가 의견" wide>
              <TextInput value={opinion} onChange={setOpinion} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
